"use strict";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
import { useLockContract } from "hooks/useLockContract";
import { useVeABXLock, useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useLockDepositStatus } from "hooks/useManagedDeposits";
import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import styled from "styled-components";
import { Flex, SpinningLoader, Text, useSporeColors } from "ui/src";
import { parseLockAmount, secondsToDays } from "utils/lockCalculations";
import { isAddress } from "viem";
import { useAccount } from "wagmi";
import { useEscrowType, useHasVoted, useLockDetails } from "../../../../hooks/useMergeValidation";
import { useModifyLockContext } from "../ModifyLockContextProvider";
import { useVoterContract, useVoterReads } from "hooks/useVoterContract";
import { useVotedLocks } from "hooks/useVotedLocks";
const Button = styled.button`
  all: unset;
  padding: 16px 10px;
  border: 1px solid ${({ theme }) => theme.surface3};
  background-color: ${({ $isDisabled, theme, $lock }) => $isDisabled ? theme.surface2 : $lock ? theme.surface2Hovered : theme.accent1};
  color: ${({ $isDisabled, theme, $lock }) => $isDisabled ? theme.accent1 : $lock ? theme.accent1 : theme.surface1};
  border-radius: 12px;
  cursor: ${({ $isDisabled }) => $isDisabled ? "not-allowed" : "pointer"};
  display: flex;
  justify-content: center;
  align-items: center;
  flex: 1;
  transition: all 0.2s ease;
  opacity: ${({ $isDisabled }) => $isDisabled ? 0.6 : 1};
  &:hover {
    opacity: ${({ $isDisabled }) => $isDisabled ? 0.6 : 0.7};
  }
`;
export default function ChangeLockAndOptionButton() {
  const { activeOption, selectedLockId, formData } = useModifyLockContext();
  const { address: account } = useAccount();
  const colors = useSporeColors();
  const [isProcessing, setIsProcessing] = useState(false);
  const { data: currentLock } = useVeABXLock(selectedLockId || void 0);
  const { isDeposited: isRelayDeposited, managedTokenId } = useLockDepositStatus(currentLock);
  const { resetVotes, transactionState: voterTransactionState } = useVoterContract();
  const { epochStart, epochVoteStart, useLastVoted } = useVoterReads();
  const { hasVoted: checkHasVoted, refetch: refetchVotedLocks } = useVotedLocks(currentLock ? [currentLock] : []);
  const { data: lastVotedTimestamp } = useLastVoted(selectedLockId || void 0);
  const hasActiveVotes = currentLock ? checkHasVoted(currentLock.id) : false;
  const { data: sourceHasVoted } = useHasVoted(formData.selectedMergeLockId);
  const { data: sourceEscrowType } = useEscrowType(formData.selectedMergeLockId);
  const { data: sourceLockDetails } = useLockDetails(formData.selectedMergeLockId);
  const { data: targetEscrowType } = useEscrowType(selectedLockId || void 0);
  const { data: targetLockDetails } = useLockDetails(selectedLockId || void 0);
  const {
    approveABX,
    increaseLockAmount,
    extendLockTime,
    lockPermanent,
    unlockPermanent,
    mergeLocks,
    transferLock,
    needsApproval,
    getFormattedABXBalance,
    isWritePending,
    isConfirming,
    isSuccess,
    writeError,
    transactionHash,
    refetchAllowance
  } = useLockContract();
  const { refetch: refetchUserLocks } = useVeABXUserLocks(account);
  const [lastAction, setLastAction] = useState(null);
  const [lastTransactionStep, setLastTransactionStep] = useState(null);
  useEffect(() => {
    if (isSuccess && lastTransactionStep) {
      if (lastTransactionStep === "approve") {
        console.log("Approval confirmed, proceeding with main action...");
        setLastTransactionStep(null);
        setTimeout(() => {
          refetchAllowance().then(() => {
            executeMainAction();
          });
        }, 1e3);
      } else if (lastTransactionStep === "execute") {
        setLastTransactionStep(null);
        const actionDisplayNames = {
          increase: "Amount Increased",
          extend: "Lock Extended",
          permanent: "Lock Made Permanent",
          unlockPermanent: "Permanent Mode Disabled",
          merge: "Locks Merged",
          transfer: "Lock Transferred",
          reset: "Votes Reset"
        };
        popupRegistry.addPopup(
          {
            type: PopupType.LockSuccess,
            content: {
              type: "success",
              title: actionDisplayNames[lastAction] || "Lock Updated",
              description: `Successfully ${lastAction} lock ${selectedLockId}`,
              hash: transactionHash,
              action: lastAction
            }
          },
          `lock-${lastAction}-${transactionHash}`,
          8e3
        );
        refetchUserLocks();
        void refetchVotedLocks?.();
        setLastAction(null);
        setIsProcessing(false);
      }
    } else if (writeError && (lastAction || lastTransactionStep)) {
      const errorMessage = writeError.message;
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied") || errorMessage.toLowerCase().includes("rejected by user");
      if (isUserRejection) {
        popupRegistry.addPopup(
          {
            type: PopupType.LockError,
            content: {
              type: "error",
              title: "Transaction Cancelled",
              description: `${lastAction} operation was cancelled by user`,
              action: lastAction
            }
          },
          `lock-${lastAction}-cancelled-${Date.now()}`,
          5e3
        );
      } else {
        const actionDisplayNames = {
          increase: "Increase Amount",
          extend: "Extend Lock",
          permanent: "Make Permanent",
          unlockPermanent: "Disable Permanent Mode",
          merge: "Merge Locks",
          transfer: "Transfer Lock",
          reset: "Reset Votes"
        };
        popupRegistry.addPopup(
          {
            type: PopupType.LockError,
            content: {
              type: "error",
              title: `${actionDisplayNames[lastAction] || "Lock Update"} Failed`,
              description: `Failed to ${lastAction} lock: ${errorMessage}`,
              action: lastAction
            }
          },
          `lock-${lastAction}-error-${Date.now()}`,
          1e4
        );
      }
      setLastAction(null);
      setLastTransactionStep(null);
      setIsProcessing(false);
    }
  }, [
    isSuccess,
    writeError,
    lastAction,
    lastTransactionStep,
    transactionHash,
    selectedLockId,
    refetchUserLocks,
    refetchAllowance,
    refetchVotedLocks
  ]);
  const getButtonText = () => {
    if (isRelayDeposited) {
      return "Withdraw from relay to modify";
    }
    switch (activeOption) {
      case "Increase":
        if (!formData.increaseAmount || formData.increaseAmount === "") {
          return "Amount required";
        }
        return "Increase";
      case "Extend":
        if (currentLock?.permanent) {
          return "Disable permanent mode";
        }
        return formData.extendToMaxLock ? "Convert to permanent" : "Extend lock time";
      case "Merge":
        return "Merge";
      case "Transfer":
        return "Transfer";
      case "Reset":
        return "Reset Votes";
      default:
        return "Update";
    }
  };
  const canExecute = () => {
    if (!account || !selectedLockId) return false;
    switch (activeOption) {
      case "Increase": {
        const amountValidation = parseLockAmount(formData.increaseAmount);
        if (!amountValidation.isValid) return false;
        const userBalance = parseFloat(getFormattedABXBalance());
        const requestedAmount = parseFloat(formData.increaseAmount);
        return requestedAmount > 0 && requestedAmount <= userBalance;
      }
      case "Extend": {
        if (!currentLock) return false;
        if (currentLock.permanent) {
          if (hasActiveVotes) return false;
          return formData.unlockPermanent;
        }
        return formData.extendDays > 0 || formData.extendToMaxLock;
      }
      case "Merge": {
        if (!formData.selectedMergeLockId || !currentLock || currentLock.managed) return false;
        if (sourceHasVoted === true) return false;
        if (sourceLockDetails?.isPermanent === true) return false;
        if (targetLockDetails && !targetLockDetails.isPermanent) {
          const now = Math.floor(Date.now() / 1e3);
          const targetEnd = Number(targetLockDetails.end);
          if (targetEnd <= now) return false;
        }
        return true;
      }
      case "Transfer": {
        if (!formData.transferToAddress || !currentLock) return false;
        if (!isAddress(formData.transferToAddress)) return false;
        if (formData.transferToAddress === "0x0000000000000000000000000000000000000000") return false;
        if (account && formData.transferToAddress.toLowerCase() === account.toLowerCase()) return false;
        return true;
      }
      case "Reset": {
        if (!currentLock || !checkHasVoted(currentLock.id)) return false;
        if (!epochStart || !epochVoteStart) return false;
        const currentTime = Math.floor(Date.now() / 1e3);
        const DISTRIBUTION_WINDOW = 6 * 60 * 60;
        if (lastVotedTimestamp) {
          const lastVoted = Number(lastVotedTimestamp);
          if (epochStart <= lastVoted) {
            return false;
          }
        }
        if (currentTime >= epochStart && currentTime < epochStart + DISTRIBUTION_WINDOW) {
          return false;
        }
        if (currentTime <= epochVoteStart) {
          return false;
        }
        return true;
      }
      default:
        return false;
    }
  };
  const executeMainAction = async () => {
    if (!canExecute() || isProcessing) return;
    setLastTransactionStep("execute");
    try {
      switch (activeOption) {
        case "Increase": {
          await increaseLockAmount({
            tokenId: selectedLockId,
            amount: formData.increaseAmount
          });
          break;
        }
        case "Extend": {
          if (!currentLock) return;
          if (currentLock.permanent && hasActiveVotes) return;
          if (currentLock.permanent) {
            if (!formData.unlockPermanent) return;
            await unlockPermanent(selectedLockId);
            break;
          }
          if (formData.extendToMaxLock) {
            await lockPermanent(selectedLockId);
          } else {
            const extensionDays = formData.extendDays;
            const currentTimeSeconds = Math.floor(Date.now() / 1e3);
            const currentUnlockTime = parseInt(currentLock.lockEnd);
            const remainingDays = Math.max(0, secondsToDays(currentUnlockTime - currentTimeSeconds));
            const totalNewDuration = remainingDays + extensionDays;
            await extendLockTime({
              tokenId: selectedLockId,
              lockDurationInDays: totalNewDuration
            });
          }
          break;
        }
        case "Merge": {
          if (!formData.selectedMergeLockId || !currentLock) return;
          await mergeLocks({
            fromTokenId: formData.selectedMergeLockId,
            toTokenId: selectedLockId
          });
          break;
        }
        case "Transfer": {
          if (!formData.transferToAddress || !currentLock) return;
          await transferLock({
            tokenId: selectedLockId,
            toAddress: formData.transferToAddress
          });
          break;
        }
        case "Reset": {
          await resetVotes(selectedLockId);
          break;
        }
      }
    } catch (error) {
      console.error("Main transaction failed:", error);
      setLastTransactionStep(null);
      throw error;
    }
  };
  const executeAction = async () => {
    if (isRelayDeposited) {
      popupRegistry.addPopup(
        {
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Relay Managed Lock",
            description: managedTokenId ? `Lock ${selectedLockId} is managed by mveABX #${managedTokenId}. Withdraw it to modify.` : "Lock is managed by a relay. Withdraw it to modify.",
            action: "withdrawRelay"
          }
        },
        `relay-lock-blocked-${selectedLockId}-${Date.now()}`,
        6e3
      );
      return;
    }
    if (!canExecute() || isProcessing) return;
    setIsProcessing(true);
    try {
      switch (activeOption) {
        case "Increase":
          setLastAction("increase");
          break;
        case "Extend":
          if (formData.unlockPermanent) {
            setLastAction("unlockPermanent");
          } else {
            setLastAction(formData.extendToMaxLock ? "permanent" : "extend");
          }
          break;
        case "Merge":
          setLastAction("merge");
          break;
        case "Transfer":
          setLastAction("transfer");
          break;
        case "Reset":
          setLastAction("reset");
          break;
      }
      if (activeOption === "Increase" && needsApproval(formData.increaseAmount)) {
        console.log("Approval needed, starting approval transaction...");
        setLastTransactionStep("approve");
        await approveABX(formData.increaseAmount);
      } else {
        await executeMainAction();
      }
    } catch (error) {
      console.error("Transaction failed:", error);
      if (lastAction) {
        const errorMessage = error instanceof Error ? error.message : "Unknown error";
        const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied") || errorMessage.toLowerCase().includes("rejected by user");
        if (isUserRejection) {
          popupRegistry.addPopup(
            {
              type: PopupType.LockError,
              content: {
                type: "error",
                title: "Transaction Cancelled",
                description: `${lastAction} operation was cancelled by user`,
                action: lastAction
              }
            },
            `lock-${lastAction}-cancelled-${Date.now()}`,
            5e3
          );
        } else {
          const actionDisplayNames = {
            increase: "Increase Amount",
            extend: "Extend Lock",
            permanent: "Make Permanent",
            merge: "Merge Locks",
            transfer: "Transfer Lock",
            reset: "Reset Votes"
          };
          popupRegistry.addPopup(
            {
              type: PopupType.LockError,
              content: {
                type: "error",
                title: `${actionDisplayNames[lastAction] || "Lock Update"} Failed`,
                description: `Failed to ${lastAction} lock: ${errorMessage}`,
                action: lastAction
              }
            },
            `lock-${lastAction}-error-${Date.now()}`,
            1e4
          );
        }
      }
      setLastAction(null);
      setLastTransactionStep(null);
    } finally {
      setIsProcessing(false);
    }
  };
  const isDisabled = isRelayDeposited || !canExecute() || isProcessing || isWritePending || isConfirming;
  const isLoading = isProcessing || isWritePending || isConfirming;
  const navigate = useNavigate();
  return <Flex mt={"$spacing36"} row gap={"$gap12"} alignItems="center">
      {
    /* <Button $lock $isDisabled={false} onClick={() => navigate('/locks')}>
      <Text variant="buttonLabel3" color={'inherit'}>
        Change Lock
      </Text>
    </Button> */
  }

      <Button onClick={executeAction} $isDisabled={isDisabled}>
        <Flex row gap={"$gap4"} alignItems="center">
          {isLoading && <SpinningLoader size={18} />}
          <Text variant="buttonLabel3" color={"inherit"}>
            {isLoading ? "Processing" : activeOption === "Increase" && formData.increaseAmount && needsApproval(formData.increaseAmount) ? "Approve & Increase" : getButtonText()}
          </Text>
        </Flex>
      </Button>
    </Flex>;
}
